package in.tucor.api.auth;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="registration_profiles") public class RegistrationProfile {
@Id @Column(name="user_id") public UUID userId; @Column(name="business_name",nullable=false) public String businessName; @Column(name="business_type",nullable=false) public String businessType; @Column(name="trade_name") public String tradeName; @Column public String category; @Column public String pan; @Column public String cin; @Column(name="year_established") public String yearEstablished; @Column public String website; @Column(name="gst_number",nullable=false) public String gstNumber; @Column(name="registration_number") public String registrationNumber; @Column(nullable=false) public String address; @Column(nullable=false) public String city; @Column(nullable=false) public String state; @Column(nullable=false) public String country="India"; @Column(nullable=false) public String pincode; @Column(name="estimated_volume_monthly") public String estimatedVolumeMonthly; @Column(name="full_name",nullable=false) public String fullName; @Column(nullable=false) public String phone; @Column(name="primary_role") public String primaryRole; @Column(name="alternate_name") public String alternateName; @Column(name="alternate_role") public String alternateRole; @Column(name="alternate_phone") public String alternatePhone; @Column(name="alternate_email") public String alternateEmail; @Column(name="warehouse_address") public String warehouseAddress; @Column(name="warehouse_contact") public String warehouseContact; @Column(name="warehouse_hours") public String warehouseHours; @Column(name="created_at",nullable=false) public Instant createdAt; @Column(name="updated_at",nullable=false) public Instant updatedAt;
@PrePersist void create(){createdAt=updatedAt=Instant.now();} @PreUpdate void update(){updatedAt=Instant.now();}
}